                                 return (
                                   <div className="flex justify-between text-slate-500">
                                     <span>Delivery Charge:</span>
                                     <span>{config.currency} {parseFloat(activeReceipt.delivery_charge || activeReceipt.delivery_charges || 0).toFixed(2)}</span>
